<?php
namespace App\Http\Controllers;
use App\Models\{Invoice,Client};
use App\Services\CurrencyService;
use Carbon\Carbon;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
class BusinessReportController extends Controller {
 private function add(int $a,int $b):int {if(($b>0&&$a>9007199254740991-$b)||($b<0&&$a< -9007199254740991-$b))throw \Illuminate\Validation\ValidationException::withMessages(['report'=>'Report amount exceeds safe precision; narrow the filters.']);return $a+$b;}
 public function show(Request $r,string $kind){
  $r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>['nullable','date_format:Y-m-d',Rule::when($r->filled('from'),'after_or_equal:from')],'client_id'=>[$kind==='statement'?'required':'nullable','integer',Rule::exists('clients','id')->where('business_id',$r->user()->business_id)],'currency'=>['nullable',Rule::in(app(CurrencyService::class)->codes())],'format'=>'nullable|in:csv']);
  $to=$r->input('to')?:today()->format('Y-m-d');$from=$r->input('from')?:Carbon::parse($to)->startOfMonth()->format('Y-m-d');abort_if($kind==='statement'&&$from>$to,422,'The statement end date must follow its start date.');
  $q=Invoice::with(['client','payments'=>fn($q)=>$q->whereDate('paid_on','<=',$to)])->whereNotIn('status',['draft','void'])->where(function($q)use($kind,$to){$q->whereDate('issue_date','<=',$to);if($kind==='statement')$q->orWhereHas('payments',fn($p)=>$p->whereDate('paid_on','<=',$to));});if($r->filled('client_id'))$q->where('client_id',$r->integer('client_id'));if($r->filled('currency'))$q->where('currency',$r->currency);abort_if((clone $q)->count()>5000,422,'Narrow the client or currency filter; this report supports 5000 invoices per request.');
  abort_if(\App\Models\Payment::whereIn('invoice_id',(clone $q)->pluck('id'))->whereDate('paid_on','<=',$to)->count()>10000,422,'This report supports 10000 payment records; narrow the client or currency filter.');
  $invoices=$q->orderBy('issue_date')->orderBy('id')->get();$groups=[];$rows=[];$asOf=Carbon::parse($to)->startOfDay();$events=0;
  foreach($invoices as $i){$key=$i->currency.':'.$i->currency_minor_units;if(!isset($groups[$key]))$groups[$key]=['currency'=>$i->currency,'minor_units'=>$i->currency_minor_units,'opening_minor'=>0,'invoiced_minor'=>0,'paid_minor'=>0,'closing_minor'=>0,'current_minor'=>0,'days_1_30_minor'=>0,'days_31_60_minor'=>0,'days_61_90_minor'=>0,'days_over_90_minor'=>0];$g=&$groups[$key];
   $date=$i->issue_date->format('Y-m-d');$paid=(int)$i->payments->sum('amount_kobo');$balance=max(0,$i->total_kobo-$paid);
   if($kind==='statement'){
    if($date<$from)$g['opening_minor']=$this->add($g['opening_minor'],$i->total_kobo);elseif($date<=$to){$g['invoiced_minor']=$this->add($g['invoiced_minor'],$i->total_kobo);$rows[]=['date'=>$date,'type'=>'invoice','reference'=>$i->number,'client'=>$i->client->name,'currency'=>$i->currency,'minor_units'=>$i->currency_minor_units,'debit_minor'=>$i->total_kobo,'credit_minor'=>0,'sort'=>'0-'.str_pad((string)$i->id,20,'0',STR_PAD_LEFT)];}
    foreach($i->payments as $p){abort_if(++$events>10000,422,'This statement has too many payment records; narrow the date or currency filter.');$date=$p->paid_on->format('Y-m-d');if($date<$from)$g['opening_minor']=$this->add($g['opening_minor'],-$p->amount_kobo);else{$g['paid_minor']=$this->add($g['paid_minor'],$p->amount_kobo);$rows[]=['date'=>$date,'type'=>'payment','reference'=>$i->number.($p->reference?' / '.$p->reference:''),'client'=>$i->client->name,'currency'=>$i->currency,'minor_units'=>$i->currency_minor_units,'debit_minor'=>0,'credit_minor'=>$p->amount_kobo,'sort'=>'1-'.str_pad((string)$p->id,20,'0',STR_PAD_LEFT)];}}
   }elseif($balance>0){$days=max(0,(int)$i->due_date->startOfDay()->diffInDays($asOf,false));$bucket=$days===0?'current_minor':($days<=30?'days_1_30_minor':($days<=60?'days_31_60_minor':($days<=90?'days_61_90_minor':'days_over_90_minor')));$g[$bucket]=$this->add($g[$bucket],$balance);$g['closing_minor']=$this->add($g['closing_minor'],$balance);$rows[]=['date'=>$i->due_date->format('Y-m-d'),'type'=>'outstanding','reference'=>$i->number,'client'=>$i->client->name,'currency'=>$i->currency,'minor_units'=>$i->currency_minor_units,'balance_minor'=>$balance,'days_overdue'=>$days,'bucket'=>$bucket];}unset($g);
  }
  if($kind==='statement'){usort($rows,fn($a,$b)=>[$a['date'],$a['sort']]<=>[$b['date'],$b['sort']]);$balances=[];foreach($groups as $key=>&$g){$g['closing_minor']=$this->add($this->add($g['opening_minor'],$g['invoiced_minor']),-$g['paid_minor']);$balances[$key]=$g['opening_minor'];}unset($g);foreach($rows as &$row){$key=$row['currency'].':'.$row['minor_units'];$balances[$key]=$this->add($balances[$key],$row['debit_minor']-$row['credit_minor']);$row['balance_minor']=$balances[$key];unset($row['sort']);}unset($row);}
  $result=['kind'=>$kind,'from'=>$kind==='statement'?$from:null,'to'=>$to,'client'=>$r->filled('client_id')?Client::withTrashed()->findOrFail($r->integer('client_id'))->only(['id','name']):null,'totals'=>array_values($groups),'rows'=>$rows];
  if($r->input('format')!=='csv')return $result;
  return response()->streamDownload(function()use($result){$f=fopen('php://output','w');$write=function($values)use($f){fputcsv($f,array_map(fn($v)=>is_string($v)&&preg_match('/^[=+@\-\t\r]/',$v)?"'".$v:$v,$values),',','"','');};$write(['Report',$result['kind'],'From',$result['from'],'To',$result['to']]);$write(['Currency','Minor digits','Opening minor','Invoiced minor','Paid minor','Closing minor','Current minor','1-30 minor','31-60 minor','61-90 minor','Over 90 minor']);foreach($result['totals'] as $g)$write(array_values($g));$write([]);$write(['Date','Type','Reference','Client','Currency','Minor digits','Debit minor','Credit minor','Balance minor','Days overdue']);foreach($result['rows'] as $row)$write([$row['date'],$row['type'],$row['reference'],$row['client'],$row['currency'],$row['minor_units'],$row['debit_minor']??0,$row['credit_minor']??0,$row['balance_minor'],$row['days_overdue']??'']);fclose($f);},$kind.'-'.$to.'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);
 }
}
